$pdo=db();$activeCondition='1=1';try{if($pdo->query("SHOW TABLES LIKE 'quote_archives'")->fetchColumn())$activeCondition='NOT EXISTS (SELECT 1 FROM quote_archives qa WHERE qa.quote_id=q.id)';}catch(Throwable $ignored){}$activeCondition.=" AND NOT EXISTS (SELECT 1 FROM moving_quote_meta mm WHERE mm.quote_id=q.id AND JSON_EXTRACT(mm.payload,'$.revision_effective_child_id')>0)";$kpis=['customers'=>0,'quotes'=>0,'waiting'=>0,'accepted'=>0];$recent=[];$errors=[];
