try{$recent=$pdo->query("SELECT q.id,q.quote_no,q.created_at,q.origin,q.destination,q.status,c.name FROM quotes q LEFT JOIN customers c ON c.id=q.customer_id WHERE ".$activeCondition." ORDER BY q.id DESC LIMIT 12")->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable $e){$errors[]='Son işlemler yüklenemedi.';}
